<?php require_once 'functions.php'; require_customer(); $id=(int)($_GET['id']??0); $s=$conn->prepare('SELECT * FROM orders WHERE id=? AND customer_id=?');$s->bind_param('ii',$id,$_SESSION['customer_id']);$s->execute();$o=$s->get_result()->fetch_assoc();if(!$o)redirect('my_orders.php');$page_title='Order Success | '.SHOP_NAME;include 'header.php';?><section class="section"><div class="success-card"><div class="success-icon">✓</div><h1>Order Placed Successfully!</h1><p>Your order <strong>#<?= (int)$o['id'] ?></strong> has been received.</p><p>Payment: <strong><?= e($o['payment_method']) ?></strong></p><?php if($o['payment_method']==='UPI'): ?><div class="notice">Pay <strong><?= money($o['total']) ?></strong> to UPI ID <strong><?= e(UPI_ID) ?></strong> and keep your transaction reference.</div><?php endif; ?><p class="muted">We will contact you on <?= e($o['phone']) ?> for delivery updates.</p><a class="btn" href="my_orders.php">View My Orders</a> <a class="btn dark" href="products.php">Continue Shopping</a></div></section><?php include 'footer.php'; ?>
